public static void main(String[] args) {
    FastScanner sc = new FastScanner();

    HashMap<Integer, Integer> coins = new HashMap<>();
    int x = Integer.parseInt(sc.next());
    coins.put(1, x);
    x = Integer.parseInt(sc.next());
    coins.put(5, x);
    x = Integer.parseInt(sc.next());
    coins.put(10, x);
    x = Integer.parseInt(sc.next());
    coins.put(50, x);
    x = Integer.parseInt(sc.next());
    coins.put(100, x);
    x = Integer.parseInt(sc.next());
    coins.put(500, x);

    int n = Integer.parseInt(sc.next());
    int[] a = new int[n];
    for (int i = 0; i < n; i++) {
        a[i] = Integer.parseInt(sc.next());
    }

    for (int i = 0; i < n; i++) {
        int amount = a[i];
        int[] denominations = {500, 100, 50, 10, 5, 1};

        for (int denom : denominations) {
            int needed = amount / denom;
            int available = coins.get(denom);
            if (needed <= available) {
                amount -= needed * denom;
                coins.put(denom, available - needed);
            } else {
                amount -= available * denom;
                coins.put(denom, 0);
            }
        }

        if (amount > 0) {
            System.out.println("No");
            return;
        }
    }

    System.out.println("Yes");
}
